{
  "title": "Discussion about working abroad in Slovakia, Austria and elsewhere",
  "topics": [
    {
      "id": "job-search-abroad",
      "title": "Experiences and advice on finding jobs abroad",
      "claims": [
        {
          "text": "People in the group have acquaintances working in Austria and Poland",
          "evidence": [3]
        },
        {
          "text": "One user sent about 100 applications and got only 3 interviews",
          "evidence": [21]
        },
        {
          "text": "A respondent found a job in 2 months after moving abroad",
          "evidence": [17]
        },
        {
          "text": "LinkedIn is recommended for job search",
          "evidence": [18]
        },
        {
          "text": "Most vacancies specify a requirement for local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Some candidates are hired despite limited local language skills",
          "evidence": [30]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        },
        {
          "text": "Salary in Europe generally higher than in Ukraine, but many ignore it",
          "evidence": [35]
        },
        {
          "text": "Applicant applied to many positions regardless of language requirement and got interviews",
          "evidence": [36]
        },
        {
          "text": "Accepting the first offer led to a low salary, though higher than a fast‑food job",
          "evidence": [37]
        },
        {
          "text": "Need to find a job by early March was a driver for accepting the low offer",
          "evidence": [40, 41]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for jobs and daily life",
      "claims": [
        {
          "text": "German is the primary workplace language in Austria",
          "evidence": [14]
        },
        {
          "text": "English can be used at work and is acceptable in many situations",
          "evidence": [15, 44, 55]
        },
        {
          "text": "B2 level is most often requested, B1 may be enough, certificates are rarely required",
          "evidence": [46]
        },
        {
          "text": "Learning the local language improves confidence in daily interactions",
          "evidence": [47, 54]
        },
        {
          "text": "The speaker feels insecure speaking English outside of work",
          "evidence": [52]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Salary expectations and market perception",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine",
          "evidence": [35]
        },
        {
          "text": "Even with higher salary offers, candidates may accept low pay to secure any job",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "networking-and-communities",
      "title": "Networking and community activities",
      "claims": [
        {
          "text": "Attending tech community channels or Discord servers is suggested for improving English",
          "evidence": [56, 57]
        },
        {
          "text": "One participant considers attending a tech event in Warsaw (wawtech.io/summer)",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Should the speaker stay in Austria long‑term?",
      "evidence": [58]
    }
  ]
}
